const listProjectsForSquad = `-- name: ListProjectsForSquad :many
SELECT id, workspace_id, title, description, icon, status, lead_type, lead_id, created_at, updated_at, priority, access, outcomes_disabled, start_date, due_date, workflow_id, creator_type, creator_id, visibility, archived_at, archived_by_type, archived_by_id, folder_id, squad_ids FROM project
WHERE workspace_id = $1::uuid
  AND $2::uuid = ANY(squad_ids)
AND ($3::uuid[] IS NULL OR NOT (COALESCE(project.id, '00000000-0000-0000-0000-000000000000'::uuid) = ANY($3::uuid[])))
ORDER BY created_at, id
`

type ListProjectsForSquadParams struct {
	WorkspaceID      pgtype.UUID   `json:"workspace_id"`
	SquadID          pgtype.UUID   `json:"squad_id"`
	HiddenProjectIds []pgtype.UUID `json:"hidden_project_ids"`
}

// The projects a squad is assigned to. A squad's active workflow changes what
// its room shows for each of them, so their pages are announced.
// MUL-8472: private projects the caller cannot see.
func (q *Queries) ListProjectsForSquad(ctx context.Context, arg ListProjectsForSquadParams) ([]Project, error) {
	rows, err := q.db.Query(ctx, listProjectsForSquad, arg.WorkspaceID, arg.SquadID, arg.HiddenProjectIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Project{}
	for rows.Next() {
		var i Project
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Title,
			&i.Description,
			&i.Icon,
			&i.Status,
			&i.LeadType,
			&i.LeadID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Priority,
			&i.Access,
			&i.OutcomesDisabled,
			&i.StartDate,
			&i.DueDate,
			&i.WorkflowID,
			&i.CreatorType,
			&i.CreatorID,
			&i.Visibility,
			&i.ArchivedAt,
			&i.ArchivedByType,
			&i.ArchivedByID,
			&i.FolderID,
			&i.SquadIds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

